 IF coalesce(actual, 'null'::jsonb) IS DISTINCT FROM $expected$[["mv_consumo_itens_semana"," SELECT produto_id,\n    date_trunc('week'::text, data::timestamp with time zone)::date AS semana,\n    sum(quantidade) AS total_saida,\n    sum(custo_total) AS custo_total\n   FROM movimentacoes_estoque\n  WHERE status = 'ATIVO'::text AND tipo !~~ 'ENTRADA%'::text AND (tipo <> ALL (ARRAY['AJUSTE'::text, 'ENTRADA_ESTORNO'::text, 'SAIDA_ESTORNO'::text]))\n  GROUP BY produto_id, (date_trunc('week'::text, data::timestamp with time zone)::date);",null,null],["mv_fin_dre_mensal"," SELECT to_char(data_competencia::timestamp with time zone, 'YYYY-MM'::text) AS mes,\n    tipo,\n    categoria_id,\n    count(*) AS qtd,\n    sum(valor) AS total\n   FROM fin_lancamentos\n  WHERE status = 'REALIZADO'::text AND tipo <> 'TRANSFERENCIA'::text\n  GROUP BY (to_char(data_competencia::timestamp with time zone, 'YYYY-MM'::text)), tipo, categoria_id;",null,null],["mv_fin_fluxo_caixa_diario"," SELECT data_competencia AS dia,\n    conta_id,\n    tipo,\n    sum(valor) AS total\n   FROM fin_lancamentos\n  WHERE status = 'REALIZADO'::text AND tipo <> 'TRANSFERENCIA'::text\n  GROUP BY data_competencia, conta_id, tipo;",null,null],["mv_giro_estoque"," SELECT p.id AS produto_id,\n    p.nome_produto,\n    p.categoria,\n    COALESCE(sum(\n        CASE\n            WHEN m.tipo ~~ 'ENTRADA%'::text AND m.tipo <> 'ENTRADA_ESTORNO'::text THEN m.quantidade\n            ELSE 0::numeric\n        END), 0::numeric) AS entradas,\n    COALESCE(sum(\n        CASE\n            WHEN m.tipo !~~ 'ENTRADA%'::text AND (m.tipo <> ALL (ARRAY['AJUSTE'::text, 'ENTRADA_ESTORNO'::text, 'SAIDA_ESTORNO'::text])) THEN m.quantidade\n            ELSE 0::numeric\n        END), 0::numeric) AS saidas,\n    ( SELECT COALESCE(sum(\n                CASE\n                    WHEN m2.tipo = ANY (ARRAY['ENTRADA_ESTORNO'::text, 'SAIDA_ESTORNO'::text]) THEN 0::numeric\n                    WHEN m2.direction = 'IN'::text THEN m2.quantidade\n                    ELSE - m2.quantidade\n                END), 0::numeric) AS \"coalesce\"\n           FROM movimentacoes_estoque m2\n          WHERE m2.produto_id = p.id AND m2.status = 'ATIVO'::text) AS saldo_atual\n   FROM produtos p\n     LEFT JOIN movimentacoes_estoque m ON m.produto_id = p.id AND m.status = 'ATIVO'::text AND m.data >= (CURRENT_DATE - '90 days'::interval)\n  WHERE p.ativo = true\n  GROUP BY p.id, p.nome_produto, p.categoria;",null,null],["mv_pedidos_status_resumo"," SELECT to_char(created_at, 'YYYY-MM'::text) AS mes,\n    status,\n    count(*) AS qtd,\n    sum(total_estimated) AS valor_total\n   FROM purchase_orders\n  GROUP BY (to_char(created_at, 'YYYY-MM'::text)), status;",null,null],["reporting.mv_consumo_itens_semana"," SELECT company_id,\n    produto_id,\n    date_trunc('week'::text, data::timestamp with time zone)::date AS semana,\n    sum(quantidade) AS total_saida,\n    sum(custo_total) AS custo_total\n   FROM movimentacoes_estoque\n  WHERE status = 'ATIVO'::text AND tipo !~~ 'ENTRADA%'::text AND (tipo <> ALL (ARRAY['AJUSTE'::text, 'ENTRADA_ESTORNO'::text, 'SAIDA_ESTORNO'::text]))\n  GROUP BY company_id, produto_id, (date_trunc('week'::text, data::timestamp with time zone)::date);",null,null],["reporting.mv_fin_dre_mensal"," SELECT company_id,\n    to_char(data_competencia::timestamp with time zone, 'YYYY-MM'::text) AS mes,\n    tipo,\n    categoria_id,\n    count(*) AS qtd,\n    sum(valor) AS total\n   FROM fin_lancamentos\n  WHERE status = 'REALIZADO'::text AND tipo <> 'TRANSFERENCIA'::text\n  GROUP BY company_id, (to_char(data_competencia::timestamp with time zone, 'YYYY-MM'::text)), tipo, categoria_id;",null,null],["reporting.mv_fin_fluxo_caixa_diario"," SELECT company_id,\n    data_competencia AS dia,\n    conta_id,\n    tipo,\n    sum(valor) AS total\n   FROM fin_lancamentos\n  WHERE status = 'REALIZADO'::text AND tipo <> 'TRANSFERENCIA'::text\n  GROUP BY company_id, data_competencia, conta_id, tipo;",null,null],["reporting.mv_giro_estoque"," SELECT p.company_id,\n    p.id AS produto_id,\n    p.nome_produto,\n    p.categoria,\n    COALESCE(sum(\n        CASE\n            WHEN m.tipo ~~ 'ENTRADA%'::text AND m.tipo <> 'ENTRADA_ESTORNO'::text THEN m.quantidade\n            ELSE 0::numeric\n        END), 0::numeric) AS entradas,\n    COALESCE(sum(\n        CASE\n            WHEN m.tipo !~~ 'ENTRADA%'::text AND (m.tipo <> ALL (ARRAY['AJUSTE'::text, 'ENTRADA_ESTORNO'::text, 'SAIDA_ESTORNO'::text])) THEN m.quantidade\n            ELSE 0::numeric\n        END), 0::numeric) AS saidas,\n    COALESCE(( SELECT sum(\n                CASE\n                    WHEN ms.tipo = ANY (ARRAY['ENTRADA_ESTORNO'::text, 'SAIDA_ESTORNO'::text]) THEN 0::numeric\n                    WHEN ms.direction = 'IN'::text THEN ms.quantidade\n                    ELSE - ms.quantidade\n                END) AS sum\n           FROM movimentacoes_estoque ms\n          WHERE ms.produto_id = p.id AND ms.status = 'ATIVO'::text), 0::numeric) AS saldo_atual\n   FROM produtos p\n     LEFT JOIN movimentacoes_estoque m ON m.produto_id = p.id AND m.status = 'ATIVO'::text AND m.data >= (CURRENT_DATE - '90 days'::interval)\n  WHERE p.ativo = true\n  GROUP BY p.company_id, p.id, p.nome_produto, p.categoria;",null,null]]$expected$::jsonb THEN RAISE EXCEPTION 'PHASE7_VIEW_DRIFT'; END IF;
